// Кейс: .qa/tests/camera-aim/CAM-001.md · план: .qa/e2e-app/specs/app.md (1.40)
// Вода в кадре: четыре точки «פינה 1..4 של שטח המים» ставятся сами внутри превью, нет «לא זוהו מים…»; галочка → «המשך» активна.
// РУЧНАЯ СЦЕНА: камера iPhone смотрит на экран Mac с видео .qa/media/empty-pool-side.mp4 на весь экран → BANCI_SCENE=water
// (иначе пропуск). Предусловие «בדיקת בטיחות» — громкость на максимуме. Мониторинг НЕ запускается («המשך» не нажимается).
import { by, assert, skip, checkedFromValue } from '../../lib/appium.mjs';
import { openCameraStep, cameraPreviewRect, waitEnabled } from '../../lib/banci.mjs';

export const name = 'Шаг 2, вода в кадре: 4 точки «פינה N של שטח המים» ставятся сами, галочка → «המשך» активна (ручная сцена BANCI_SCENE=water) #8dc640 @iphone @app @prod-safe';
export const NO_WATER = 'לא זוהו מים באזור שסומן';

export default async function (app) {
  if (process.env.BANCI_SCENE !== 'water') skip('ручная сцена: открыть на Mac на весь экран .qa/media/empty-pool-side.mp4, направить камеру iPhone и запустить с BANCI_SCENE=water');

  const water = await openCameraStep(app);
  const { rect: pv } = await cameraPreviewRect(app);
  assert(pv, 'ОШИБКА ТЕСТА: блок превью камеры не найден (cameraPreviewRect)');

  const pts = [];
  for (let i = 1; i <= 4; i++) {
    const p = await app.waitFor(by.contains(`פינה ${i} של שטח המים`), { timeout: 20000, what: `точка «פינה ${i} של שטח המים»` });
    const r = await p.rect();
    const c = { x: r.x + r.width / 2, y: r.y + r.height / 2 };
    assert(c.x >= pv.x && c.x <= pv.x + pv.width && c.y >= pv.y && c.y <= pv.y + pv.height, `точка ${i} внутри превью: (${c.x}, ${c.y})`);
    pts.push(c);
  }
  const xs = pts.map((p) => p.x), ys = pts.map((p) => p.y);
  assert(Math.max(...xs) - Math.min(...xs) > 20 && Math.max(...ys) - Math.min(...ys) > 20, `точки образуют зону, а не сливаются: ${JSON.stringify(pts)}`);
  console.log(`  точки (автоконтур): ${pts.map((p) => `(${Math.round(p.x)},${Math.round(p.y)})`).join(' ')}`);

  if (checkedFromValue(await water.attr('value')) !== true) await water.click();
  const next = await app.waitFor(by.exact('המשך', 'Button'), { what: '«המשך» на шаге 2' });
  await waitEnabled(next, true, { timeout: 15000, what: '«המשך» при воде в кадре и галочке' });
  assert(!(await app.exists(by.contains(NO_WATER))), `при воде в кадре нет «${NO_WATER}…» (если есть — проверить сцену: видео бассейна на весь экран Mac)`);
  await app.screenshot('8dc640-auto-water');
  await app.restart();
}
